import { Request, Response } from 'express';
import bcrypt from 'bcryptjs';
import User from '../models/User';
import generateToken from '../utils/generateToken';

// @desc    Register a new Shop Owner
// @route   POST /api/auth/register-shop
// @access  Public
export const registerShopOwner = async (req: Request, res: Response): Promise<void> => {
  try {
    const { name, email, password } = req.body;

    // 1. Validation
    if (!name || !email || !password) {
      res.status(400).json({ message: 'Please fill all fields' });
      return;
    }

    // 2. Check if user exists
    const userExists = await User.findOne({ email });
    if (userExists) {
      res.status(400).json({ message: 'User already exists' });
      return;
    }

    // 3. Hash password
    const salt = await bcrypt.genSalt(10);
    const hashedPassword = await bcrypt.hash(password, salt);

    // 4. Create User (Role: OWNER)
    const user = await User.create({
      name,
      email,
      password: hashedPassword,
      role: 'OWNER'
    });

    if (user) {
      generateToken(res, user._id.toString());
      res.status(201).json({
        _id: user._id,
        name: user.name,
        email: user.email,
        role: user.role,
        message: 'Shop Owner registered successfully'
      });
    } else {
      res.status(400).json({ message: 'Invalid user data' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Server Error' });
  }
};

// @desc    Login User (Shop Owner or Employee)
// @route   POST /api/auth/login
// @access  Public
export const loginUser = async (req: Request, res: Response): Promise<void> => {
  try {
    const { email, password } = req.body;

    // 1. Find user by email (Explicitly select password because we hid it in Model)
    const user = await User.findOne({ email }).select('+password');

    // 2. Check password
    if (user && user.password && (await bcrypt.compare(password, user.password))) {
      const token = generateToken(res, user._id.toString());
      
      res.json({
        _id: user._id,
        name: user.name,
        email: user.email,
        role: user.role,
        token: token 
      });
    } else {
      res.status(401).json({ message: 'Invalid email or password' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Server Error' });
  }
};

import { Request, Response } from 'express';
import s3, { BUCKET_NAME } from '../config/s3';
import crypto from 'crypto';
import { v4 as uuidv4 } from 'uuid';

// Type definition for Multer file (Standard Express type)
interface MulterRequest extends Request {
  file?: Express.Multer.File;
}

// @desc    Upload file to MinIO and get Hash
// @route   POST /api/upload
// @access  Private (Student)
export const uploadFile = async (req: MulterRequest, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ message: 'No file uploaded' });
      return;
    }

    // 1. Generate SHA-256 Hash (The "Fingerprint")
    const fileBuffer = req.file.buffer;
    const hashSum = crypto.createHash('sha256');
    hashSum.update(fileBuffer);
    const fileHash = hashSum.digest('hex');

    // 2. Generate a unique filename for storage (keep original extension)
    const fileExt = req.file.originalname.split('.').pop();
    const storageKey = `${uuidv4()}.${fileExt}`;

    // 3. Upload to MinIO (S3)
    const params = {
      Bucket: BUCKET_NAME,
      Key: storageKey,
      Body: fileBuffer,
      ContentType: req.file.mimetype,
    };

    const uploadResult = await s3.upload(params).promise();

    // 4. Return the Keys to Frontend
    // We do NOT save to DB yet. We only return the ID. 
    // The Frontend will send this ID back when the user clicks "Pay".
    res.status(201).json({
      message: 'File uploaded successfully',
      originalName: req.file.originalname,
      storageKey: uploadResult.Key, // The hidden ID
      fileHash: fileHash,           // The grouping key
      location: uploadResult.Location
    });

  } catch (error) {
    console.error('Upload Error:', error);
    res.status(500).json({ message: 'File upload failed' });
  }
};

// ... existing imports
// Add this import if missing:
