                Pay & Print
              </button>
            </div>
          </div>
        </div>

      </main>
    </div>
  );
};

export default StudentDashboard;

import React, { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../context/AuthContext';
import api from '../services/api';
import toast from 'react-hot-toast';
import { LayoutDashboard, LogOut, Printer, RefreshCw, CheckCircle, Clock, Copy, AlertTriangle, FileText, Layers, Palette } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Link } from 'react-router-dom';

const ShopDashboard = () => {
  const { user, logout } = useContext(AuthContext)!;
  const navigate = useNavigate();
  const [orders, setOrders] = useState<any[]>([]);
  const [shop, setShop] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({ pending: 0, printed: 0, revenue: 0 });

  // ... fetchShopDetails (Keep same) ...
  const fetchShopDetails = async () => {
    try {
      const { data } = await api.get('/shops/my-shop');
      setShop(data);
    } catch (err) { console.error(err); }
  };

  // ... fetchOrders (Keep same) ...
  const fetchOrders = async () => {
    try {
      // Don't set loading true on background refreshes to avoid flickering
      const { data } = await api.get('/orders/shop');
      setOrders(data);
      const pending = data.filter((o: any) => o.orderStatus === 'QUEUED').length;
      const printed = data.filter((o: any) => o.orderStatus === 'COMPLETED').length;
      const revenue = data.reduce((sum: number, o: any) => sum + (o.totalAmount || 0), 0);
      setStats({ pending, printed, revenue });
    } catch (err) { }
  };

  useEffect(() => {
    fetchShopDetails();
    fetchOrders();
    const interval = setInterval(fetchOrders, 5000); // Faster refresh (5s)
    return () => clearInterval(interval);
  }, []);

  // --- THE FIX: Call API to update Database ---
  const markCompleted = async (orderId: string) => {
    try {
      // 1. Call Backend
      await api.put(`/orders/${orderId}/status`, { status: 'COMPLETED' });
      
      // 2. Optimistic Update (Immediate UI change)
      setOrders(orders.map(o => o._id === orderId ? { ...o, orderStatus: 'COMPLETED' } : o));
      toast.success('Order Completed');
      
      // 3. Update Stats immediately
      setStats(prev => ({ 
        ...prev, 
        pending: prev.pending - 1, 
        printed: prev.printed + 1 
      }));

    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const handleLogout = () => { logout(); navigate('/login'); };
  const forceShowID = async () => { /* Keep from previous step */ };

  // --- NEW: Visual Badges for Specifications ---
  const renderSpecs = (config: any) => {
    return (
      <div className="flex flex-wrap gap-2 mt-1">
        {/* Color Badge */}
        <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase border flex items-center gap-1
          ${config.color === 'color' ? 'bg-pink-100 text-pink-700 border-pink-200' : 'bg-slate-100 text-slate-600 border-slate-200'}
        `}>
          <Palette size={10} /> {config.color === 'color' ? 'COLOR' : 'B&W'}
        </span>

        {/* Sides Badge */}
        <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase border flex items-center gap-1
          ${config.side === 'double' ? 'bg-blue-100 text-blue-700 border-blue-200' : 'bg-orange-100 text-orange-700 border-orange-200'}
        `}>
          <Layers size={10} /> {config.side === 'double' ? 'DUPLEX' : 'SINGLE'}
        </span>

        {/* Copies Badge */}
        {config.copies > 1 && (
          <span className="px-2 py-1 rounded text-[10px] font-bold uppercase bg-purple-100 text-purple-700 border border-purple-200">
            {config.copies} COPIES
          </span>
        )}
      </div>
    );
  };

  return (
    <div className="flex h-screen bg-slate-50">
      {/* Sidebar (Same) */}
      <aside className="w-64 bg-secondary text-white hidden md:flex flex-col">
        <div className="p-6 border-b border-slate-700">
          <h2 className="text-xl font-bold flex items-center gap-2"><Printer className="text-primary"/> XeroxSaaS</h2>
          <p className="text-xs text-slate-400 mt-1">Partner Portal</p>
        </div>
        <nav className="flex-1 p-4"><a href="#" className="flex items-center gap-3 px-4 py-3 bg-white/10 text-primary rounded-xl"><LayoutDashboard size={20} /> Dashboard</a></nav>
        <div className="p-4 border-t border-slate-700"><button onClick={handleLogout} className="w-full flex items-center gap-2 px-4 py-2 text-sm text-red-400 hover:bg-red-400/10 rounded-lg"><LogOut size={16} /> Logout</button></div>
      </aside>

      <main className="flex-1 overflow-auto">
        <header className="bg-white border-b border-slate-200 p-6 flex justify-between items-center sticky top-0 z-10">
          <div>
            <h1 className="text-2xl font-bold text-slate-800">Shop Dashboard</h1>
             {shop && <div className="flex items-center gap-2 text-xs text-slate-500 mt-1 bg-slate-100 px-2 py-1 rounded w-fit"><span>ID: <span className="font-mono">{shop._id}</span></span></div>}
          </div>
          <div className="flex gap-4">
             <button onClick={fetchOrders} className="p-2 text-slate-500 hover:text-primary-hover"><RefreshCw size={20}/></button>
             <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-sm font-medium border border-green-200 flex items-center gap-2"><span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span> Online</span>
          </div>
        </header>

        <div className="p-6 max-w-7xl mx-auto space-y-8">
           {/* Stats (Same) */}
           <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
              <p className="text-slate-500 text-sm mb-1">Queue Size</p><h3 className="text-3xl font-bold text-slate-900">{stats.pending}</h3>
            </div>
            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
              <p className="text-slate-500 text-sm mb-1">Completed Today</p><h3 className="text-3xl font-bold text-slate-900">{stats.printed}</h3>
            </div>
            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
              <p className="text-slate-500 text-sm mb-1">Revenue Estimate</p><h3 className="text-3xl font-bold text-primary-hover">₹{stats.revenue.toFixed(2)}</h3>
            </div>
          </div>

          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-6 border-b border-slate-100"><h3 className="font-bold text-lg">Incoming Orders</h3></div>
            <table className="w-full text-left border-collapse">
              <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-semibold">
                <tr><th className="p-4">Order ID</th><th className="p-4">Student</th><th className="p-4">Files & Config</th><th className="p-4">Status</th><th className="p-4">Action</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {orders.length === 0 ? (
                  <tr><td colSpan={5} className="p-8 text-center text-slate-400">No orders yet.</td></tr>
                ) : (
                  orders.map((order) => (
                    <tr key={order._id} className="hover:bg-slate-50 transition-colors">
                      <td className="p-4 font-mono text-sm text-slate-500">#{order._id.slice(-6)}</td>
                      <td className="p-4 font-medium">{order.user?.name || 'Guest'}</td>
                      
                      {/* IMPROVED FILE DISPLAY */}
                      <td className="p-4">
                        <div className="space-y-3">
                          {order.items.map((item: any, idx: number) => (
                            <div key={idx} className="flex flex-col gap-1">
                              <div className="flex items-center gap-2 font-medium text-slate-700">
                                <FileText size={16} className="text-slate-400" />
                                {item.originalName}
                                
                                {/* NEW: View Button */}
                                <button 
                                  onClick={async () => {
                                    try {
                                      const { data } = await api.post('/upload/presigned', { storageKey: item.storageKey });
                                      window.open(data.url, '_blank'); // Open PDF in new tab
                                    } catch (e) {
                                      toast.error('Could not open file');
                                    }
                                  }}
                                  className="ml-2 text-[10px] bg-slate-200 hover:bg-slate-300 text-slate-700 px-2 py-0.5 rounded font-bold transition-colors"
                                  title="Open Secure Link"
                                >
                                  VIEW
                                </button>
                              </div>
                              <div className="flex items-center gap-2 text-xs text-slate-500 pl-6">
                                <span>Range: <b>{item.config.pageRange || 'All'}</b></span>
                                <span>•</span>
                                <span>{item.pageCount} Pages</span>
                              </div>
                              {/* RENDER BADGES */}
                              <div className="pl-6">
                                {renderSpecs(item.config)}
                              </div>
                            </div>
                          ))}
                        </div>
                      </td>

                      <td className="p-4">
                        <span className={`px-3 py-1 rounded-full text-xs font-bold inline-flex items-center gap-1
                          ${order.orderStatus === 'QUEUED' ? 'bg-yellow-100 text-yellow-700' : 'bg-green-100 text-green-700'}`}>
                          {order.orderStatus === 'QUEUED' ? <Clock size={12}/> : <CheckCircle size={12}/>}
                          {order.orderStatus}
                        </span>
                      </td>

                      <td className="p-4">
                        {order.orderStatus === 'QUEUED' ? (
                          <button onClick={() => markCompleted(order._id)} className="btn bg-slate-900 text-white hover:bg-slate-800 text-xs py-2 px-4 shadow-none">
                            <Printer size={16} /> Print & Close
                          </button>
                        ) : (
                          <span className="text-slate-400 text-sm">Archived</span>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </main>
    </div>
  );
};

