import React, { useState, useContext } from 'react';
import api from '../services/api';
import { AuthContext } from '../context/AuthContext';
import FileUpload from '../components/FileUpload';
import toast from 'react-hot-toast';
import { Store, ShoppingCart, LogOut, FileText, Trash2, Eye, Edit2 } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

interface CartItem {
  storageKey: string;
  originalName: string;
  fileHash: string;
  pageCount: number;
  previewUrl?: string; 
  config: {
    color: 'bw' | 'color';
    side: 'single' | 'double';
    copies: number;
    pageRange: string; 
  };
}

const StudentDashboard = () => {
  const { user, logout } = useContext(AuthContext)!;
  const navigate = useNavigate();
  
  // MOCK SHOP with a VALID MongoDB ID Format (Prevents CastError)
  const [selectedShop] = useState<any>({
    _id: '6978cc7a71919ea3033427f0', // <--- This is a valid "Fake" ID
    name: 'Campus Copy Center (Mock)',
    pricing: { baseRate: { bw: 2, color: 10 } }
  });

  const [cart, setCart] = useState<CartItem[]>([]);

  const handleUploadComplete = (files: any[]) => {
    const newItems = files.map(f => ({
      ...f,
      config: { 
        color: 'bw', 
        side: 'single', 
        copies: 1,
        pageRange: 'All' 
      }
    }));
    setCart(prev => [...prev, ...newItems]);
    toast.success(`${files.length} file(s) added!`);
  };

  const updateConfig = (index: number, key: string, value: any) => {
    const newCart = [...cart];
    newCart[index].config = { ...newCart[index].config, [key]: value };
    setCart(newCart);
  };

  const updatePageCount = (index: number, newCount: number) => {
    const newCart = [...cart];
    newCart[index].pageCount = newCount;
    setCart(newCart);
  };

  const calculateTotal = () => {
    return cart.reduce((total, item) => {
      const rate = item.config.color === 'bw' 
        ? selectedShop.pricing.baseRate.bw 
        : selectedShop.pricing.baseRate.color;
      return total + (rate * item.pageCount * item.config.copies);
    }, 0);
  };

  const handleCheckout = async () => {
    if (cart.length === 0) return;
    try {
      // NOTE: This will create an Order linked to a "Ghost" shop. 
