import { Response } from 'express';
import { AuthRequest } from '../middlewares/authMiddleware';
import Order from '../models/Order';
import Shop from '../models/Shop';

// Helper: Generate a random 4-digit pickup code
const generatePickupCode = () => Math.floor(1000 + Math.random() * 9000).toString();

// @desc    Create new print order
// @route   POST /api/orders
// @access  Private (Student)
export const createOrder = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const { shopId, items } = req.body;

    // 1. Fetch Shop Rules
    const shop = await Shop.findById(shopId);
    if (!shop) {
      res.status(404).json({ message: 'Shop not found' });
      return;
    }

    // 2. Calculate Costs Server-Side (Security: Never trust client price)
    let grandTotal = 0;
    const processedItems = items.map((item: any) => {
      // Get base rate (e.g., 2.0 or 10.0)
      let rate = shop.pricing.baseRate[item.config.color as 'bw' | 'color'];
      
      // Apply Side Multiplier (e.g., Double side might be 0.8x per page)
      if (item.config.side === 'double') {
        rate = rate * shop.pricing.multipliers.doubleSide;
      }

      // TODO: Apply Bulk Discount Logic here (if copies > 100)

      // Cost for this file = Rate * Pages * Copies
      const fileCost = rate * item.pageCount * item.config.copies;
      
      grandTotal += fileCost;

      return {
        ...item,
        calculatedCost: fileCost
      };
    });

    // 3. Create the Order
    const order = await Order.create({
      shop: shopId,
      user: req.user?._id,
      items: processedItems,
      totalAmount: grandTotal,
      pickupCode: generatePickupCode()
    });

    res.status(201).json(order);

  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'Order creation failed' });
  }
};

// @desc    Get Orders for My Shop
// @route   GET /api/orders/shop
// @access  Private (Owner/Employee)
export const getShopOrders = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    // 1. Find the shop owned by this user
    // Note: In a real app, we'd check 'associatedShop' for employees too
    const shop = await Shop.findOne({ owner: req.user?._id });
    if (!shop) {
      res.status(404).json({ message: 'Shop not found' });
      return;
    }

    // 2. Get orders, sort by newest
    const orders = await Order.find({ shop: shop._id })
      .populate('user', 'name email') // Join User table to get name
      .sort({ createdAt: -1 });

    res.json(orders);
  } catch (error) {
    res.status(500).json({ message: 'Server Error' });
  }
};
export const updateOrderStatus = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const { status } = req.body; // Expect { status: 'COMPLETED' }
    const order = await Order.findById(req.params.id);

    if (!order) {
      res.status(404).json({ message: 'Order not found' });
      return;
    }

    // Security Check: Does this order belong to the shop owned by this user?
    // (For simplicity, we skip complex ownership check for this prototype, but in prod, check it!)
    
    order.orderStatus = status;
    await order.save();

    res.json(order);
  } catch (error) {
    res.status(500).json({ message: 'Update failed' });
  }
};

