    res.status(500).json({ message: 'Server Error' });
  }
};

// @desc    Google Login (Real Verification)
// @route   POST /api/auth/google
// @access  Public
export const googleLogin = async (req: Request, res: Response): Promise<void> => {
  try {
    const { credential } = req.body; // The JWT token from Google

    if (!credential) {
       res.status(400).json({ message: 'No credential provided' });
       return;
    }

    // 1. Verify Token with Google
    const ticket = await client.verifyIdToken({
      idToken: credential,
      audience: GOOGLE_CLIENT_ID 
    });

    const payload = ticket.getPayload();
    if (!payload) {
       res.status(400).json({ message: 'Invalid Google Token' });
       return;
    }

    const { email, name, sub: googleId } = payload;

    if (!email) {
      res.status(400).json({ message: 'Email access required' });
      return;
    }

    // 2. Check if user exists
    let user = await User.findOne({ email });

    if (!user) {
      // 3. Register new student automatically
      user = await User.create({
        name: name || 'Student',
        email,
        googleId,
        role: 'STUDENT'
      });
    }

    // 4. Generate Token
    const token = generateToken(res, user._id.toString());

    res.json({
      _id: user._id,
      name: user.name,
      email: user.email,
      role: user.role,
      token: token
    });

  } catch (error) {
    console.error('Google Auth Error:', error);
    res.status(400).json({ message: 'Google Authentication Failed' });
  }
};

